import{_ as a,o,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"শুধুমাত্র জ্ঞান ফেরতের নীতি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/87-仅回传知识原则.md","filePath":"bn/87-仅回传知识原则.md"}'),d={name:"bn/87-仅回传知识原则.md"};function l(i,t,u,h,q,n){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="শুধুমাত্র-জ্ঞান-ফেরতের-নীতি" tabindex="-1">শুধুমাত্র জ্ঞান ফেরতের নীতি <a class="header-anchor" href="#শুধুমাত্র-জ্ঞান-ফেরতের-নীতি" aria-label="Permalink to &quot;শুধুমাত্র জ্ঞান ফেরতের নীতি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>87</td></tr><tr><td>মডিউল</td><td>আন্তঃ-তল মিথস্ক্রিয়া ও সময় নিয়ম</td></tr><tr><td>মূল কীওয়ার্ড</td><td>শুধুমাত্র জ্ঞান ফেরত, তথ্য বিশুদ্ধকরণ, পদার্থ ফেরত নিষিদ্ধ, জ্ঞান এনকোডিং, ফেরত অডিট</td></tr></tbody></table><h2 id="_1-নীতির-আইনি-পটভূমি-ও-মূল-দর্শন" tabindex="-1">1. নীতির আইনি পটভূমি ও মূল দর্শন <a class="header-anchor" href="#_1-নীতির-আইনি-পটভূমি-ও-মূল-দর্শন" aria-label="Permalink to &quot;1. নীতির আইনি পটভূমি ও মূল দর্শন&quot;">​</a></h2><p>&quot;শুধুমাত্র জ্ঞান ফেরত&quot; নীতি হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার আন্তঃ-তল ও সময় প্রত্যাবর্তন প্রত্নতত্ত্বের মৌলিক নীতিগুলির মধ্যে একটি, যার আইনি উৎস &quot;সিম্বায়োসিস সংবিধান&quot; এর অষ্টচত্বাবধিংশ অনুচ্ছেদে ফিরে যাওয়া যায়: &quot;অন্য কোনো তল বা অন্য কোনো সময়কাল থেকে অর্জিত পদার্থ, শক্তি ও জীবিত বস্তু, বিশেষ অনুমতি ছাড়া নিজের তলে আনা যাবে না; প্রত্নতত্ত্ব কার্যকলাপের বৈধ ফলাফল শুধুমাত্র বিমূর্ত জ্ঞান ও তথ্যের মধ্যে সীমাবদ্ধ।&quot; এই নীতির প্রতিষ্ঠা, হেংইয়ান-ঝৌ প্রাথমিক আন্তঃ-তল অন্বেষণের যন্ত্রণাদায়ক শিক্ষার সারাংশ করার পরে করা একটি প্রণালীগত পছন্দ।</p><p>অ্যাঙ্কর সিম্বায়োসিস সভ্যতা প্রতিষ্ঠার প্রাথমিক দিকে, আন্তঃ-তল অন্বেষণ এখনও অনিয়ন্ত্রিত অবস্থায় ছিল। কিছু অন্বেষক অন্য তলের পদার্থের নমুনা, শক্তি স্ফটিক এমনকি জীবিত বস্তু নিজের তলে নিয়ে এসে গবেষণা করত, যার ফলে একাধিক গুরুতর &quot;আন্তঃ-তল দূষণ ঘটনা&quot; ঘটেছে। সবচেয়ে বিখ্যাত মামলা হলো &quot;ভিন্ন স্ফটিক ঘটনা&quot; — একটি শক্তি প্রকাশ তল থেকে আনা শক্তি স্ফটিক, যার আইনি প্যারামিটার নিজের তলের সাথে সামঞ্জস্যপূর্ণ না হওয়ায়, নিজের তলের আইন নেটওয়ার্কে তিন বছর চলমান আইনি ব্যাঘাত সৃষ্টি করেছিল, যার ফলে তিনটি তারকা অঞ্চলের সাধন ব্যবস্থায় অস্বাভাবিকতা দেখা দিয়েছিল, হাজার হাজার সাধক বিভিন্ন মাত্রার ক্ষতিগ্রস্ত হয়েছিল। পরবর্তী তদন্তে দেখা গেছে যে, যদি সেই সময় &quot;শুধুমাত্র জ্ঞান ফেরত&quot; নীতি মেনে চলা হত, তবে এই বিপর্যয়টি সম্পূর্ণরূপে এড়ানো যেত।</p><p>&quot;শুধুমাত্র জ্ঞান ফেরত&quot; নীতির মূল দর্শন হলো: জ্ঞান হলো আন্তঃ-সভ্যতা যোগাযোগে একমাত্র নিরাপদ মাধ্যম। পদার্থ ও শক্তি তাদের উৎস তলের আইনি তথ্য বহন করে, ভিন্ন আইনি পরিবেশে প্রবেশ করার পর অপ্রত্যাশিত প্রতিক্রিয়া সৃষ্টি করতে পারে; আর জ্ঞান বিমূর্ত তথ্য হিসেবে, উপযুক্ত এনকোডিং ও বিশুদ্ধকরণের পরে, তার উৎস তলের আইনি ছাপকে বিচ্ছিন্ন করে আন্তঃ-তল ভাগাভাগিযোগ্য নিরাপদ সম্পদে রূপান্তরিত হতে পারে।</p><h2 id="_2-জ্ঞান-এর-সংজ্ঞা-ও-শ্রেণীবিভাগ" tabindex="-1">2. &quot;জ্ঞান&quot; এর সংজ্ঞা ও শ্রেণীবিভাগ <a class="header-anchor" href="#_2-জ্ঞান-এর-সংজ্ঞা-ও-শ্রেণীবিভাগ" aria-label="Permalink to &quot;2. &quot;জ্ঞান&quot; এর সংজ্ঞা ও শ্রেণীবিভাগ&quot;">​</a></h2><p>&quot;শুধুমাত্র জ্ঞান ফেরত&quot; নীতির আইনি কাঠামোর অধীনে, &quot;জ্ঞান&quot; এর কঠোর সংজ্ঞা ও শ্রেণীবিভাগ রয়েছে। সব তথ্যকে &quot;জ্ঞান&quot; হিসেবে বিবেচনা করে স্বাধীনভাবে ফেরত দেওয়া যায় না — শুধুমাত্র &quot;তথ্য বিশুদ্ধকরণ&quot; প্রক্রিয়ার মধ্য দিয়ে গেছে এবং কোনো আইনি দূষণ বহন করছে না বলে নিশ্চিত বিমূর্ত তথ্যই ফেরতের মানদণ্ড পূরণ করে।</p><p>জ্ঞান তার বিমূর্ততার মাত্রা ও নিরাপত্তার স্তর অনুযায়ী তিন শ্রেণীতে বিভক্ত:</p><table tabindex="0"><thead><tr><th>জ্ঞানের শ্রেণী</th><th>সংজ্ঞা</th><th>নিরাপত্তার স্তর</th><th>ফেরতের প্রয়োজনীয়তা</th></tr></thead><tbody><tr><td>প্রথম শ্রেণীর জ্ঞান (বিশুদ্ধ বিমূর্ত জ্ঞান)</td><td>সম্পূর্ণরূপে পদার্থ বাহক থেকে বিচ্ছিন্ন বিমূর্ত ধারণা, গাণিতিক উপপাদ্য, যৌক্তিক ডিডাকশন, দার্শনিক চিন্তা ইত্যাদি</td><td>সর্বোচ্চ (সবুজ)</td><td>সরাসরি ফেরত দেওয়া যায়, বিশেষ অনুমোদনের প্রয়োজন নেই</td></tr><tr><td>দ্বিতীয় শ্রেণীর জ্ঞান (বর্ণনামূলক জ্ঞান)</td><td>বস্তুনিষ্ঠ বস্তুর বর্ণনামূলক তথ্য, যার মধ্যে ঐতিহাসিক রেকর্ড, ভৌগলিক ডেটা, জৈব বৈশিষ্ট্য, সাংস্কৃতিক বর্ণনা ইত্যাদি অন্তর্ভুক্ত</td><td>মাঝারি (হলুদ)</td><td>তথ্য বিশুদ্ধকরণ প্রক্রিয়ার মধ্য দিয়ে যেতে হবে, তল ব্যবস্থাপনা ব্যুরোর অনুমোদনের পর ফেরত দেওয়া হবে</td></tr><tr><td>তৃতীয় শ্রেণীর জ্ঞান (প্রযুক্তিগত জ্ঞান)</td><td>নির্দিষ্ট প্রযুক্তিগত প্যারামিটার, প্রকৌশলগত পরিকল্পনা, সাধন পদ্ধতি সম্বলিত ব্যবহারিক জ্ঞান</td><td>কম (কমলা)</td><td>কঠোর তথ্য বিশুদ্ধকরণ ও নিরাপত্তা মূল্যায়নের মধ্য দিয়ে যেতে হবে, অ্যাঙ্কর কাউন্সিলের বিশেষ অনুমোদনের পর ফেরত দেওয়া হবে</td></tr></tbody></table><p>নিম্নলিখিত বিষয়গুলো &quot;জ্ঞান&quot; শ্রেণীর অন্তর্গত নয়, কঠোরভাবে ফেরত দেওয়া নিষিদ্ধ: কোনো রকমের পদার্থের নমুনা (অণুজীব, কোষ, জিনের টুকরো সহ), কোনো রকমের শক্তি স্ফটিক বা শক্তি সঞ্চয় ডিভাইস, কোনো স্বায়ত্তশাসিত চেতনা সম্পন্ন জীবিত বস্তু বা চেতনা বস্তু, কোনো তথ্য বিশুদ্ধকরণের মধ্য দিয়ে যায়নি এমন মূল ডেটা, এবং লুঠের মতো সাধনে ব্যবহার করা যেতে পারে এমন কোনো প্রযুক্তিগত বিস্তারিত।</p><h2 id="_3-তথ্য-বিশুদ্ধকরণ-প্রযুক্তি" tabindex="-1">3. তথ্য বিশুদ্ধকরণ প্রযুক্তি <a class="header-anchor" href="#_3-তথ্য-বিশুদ্ধকরণ-প্রযুক্তি" aria-label="Permalink to &quot;3. তথ্য বিশুদ্ধকরণ প্রযুক্তি&quot;">​</a></h2><p>তথ্য বিশুদ্ধকরণ হলো ফেরত দেওয়া জ্ঞানের নিরাপত্তা নিশ্চিত করার মূল প্রযুক্তিগত ধাপ। এর মূল লক্ষ্য হলো মূল তথ্যে বহন করা উৎস তলের আইনি ছাপকে সম্পূর্ণরূপে বিচ্ছিন্ন করা, শুধুমাত্র বিশুদ্ধ অর্থের বিষয়বস্তু রেখে দেওয়া। তথ্য বিশুদ্ধকরণ প্রক্রিয়া চারটি ধাপে বিভক্ত:</p><h3 id="_3-1-তথ্য-ডিকনস্ট্রাকশন" tabindex="-1">3.1 তথ্য ডিকনস্ট্রাকশন <a class="header-anchor" href="#_3-1-তথ্য-ডিকনস্ট্রাকশন" aria-label="Permalink to &quot;3.1 তথ্য ডিকনস্ট্রাকশন&quot;">​</a></h3><p>প্রথমে ফেরত দেওয়া মূল তথ্যকে কাঠামোগতভাবে বিশ্লেষণ করা হয়, &quot;অর্থের বিষয়বস্তু&quot; ও &quot;বাহকের ছাপ&quot; দুটি অংশে বিভক্ত করা হয়। অর্থের বিষয়বস্তু হলো তথ্য যা প্রকাশ করতে চায় সেই বিমূর্ত অর্থ, বাহকের ছাপ হলো তথ্য সঞ্চয় ও ট্রান্সমিশন প্রক্রিয়াতে শোষিত উৎস তলের আইনি প্যারামিটার। তথ্য ডিকনস্ট্রাকশন &quot;অর্থ-বাহক বিচ্ছিন্ন অ্যালগরিদম&quot; এর মাধ্যমে বাস্তবায়িত হয়, এই অ্যালগরিদমটি তথ্যের মধ্যে থাকা অর্থের উপাদান ও আইনি উপাদানকে চিনতে ও বিচ্ছিন্ন করতে সক্ষম।</p><h3 id="_3-2-আইনি-বিচ্ছিন্নকরণ" tabindex="-1">3.2 আইনি বিচ্ছিন্নকরণ <a class="header-anchor" href="#_3-2-আইনি-বিচ্ছিন্নকরণ" aria-label="Permalink to &quot;3.2 আইনি বিচ্ছিন্নকরণ&quot;">​</a></h3><p>বিচ্ছিন্ন করা বাহকের ছাপের উপর সম্পূর্ণ আইনি বিচ্ছিন্নকরণ করা হয়। বিচ্ছিন্নকরণের পদ্ধতি হলো তথ্যকে &quot;আইনি নিরপেক্ষতা চ্যানেল&quot; এর মধ্য দিয়ে পাঠানো — এটি একটি বিশেষ ট্রান্সমিশন চ্যানেল যার আইনি প্যারামিটার সম্পূর্ণরূপে নিরপেক্ষ হিসেবে সেট করা হয়েছে, তথ্য যখন এর মধ্য দিয়ে যায়, তখন তার দ্বারা বহন করা সমস্ত অ-নিরপেক্ষ আইনি প্যারামিটার চ্যানেলের প্রাচীর দ্বারা শোষিত হয়। আইনি বিচ্ছিন্নকরণের পর, তথ্যে আর কোনো উৎস তলের আইনি ছাপ থাকে না।</p><h3 id="_3-3-অর্থের-পুনর্নির্মাণ" tabindex="-1">3.3 অর্থের পুনর্নির্মাণ <a class="header-anchor" href="#_3-3-অর্থের-পুনর্নির্মাণ" aria-label="Permalink to &quot;3.3 অর্থের পুনর্নির্মাণ&quot;">​</a></h3><p>আইনি বিচ্ছিন্নকরণের ভিত্তিতে, অর্থের বিষয়বস্তুর পুনরায় এনকোডিং করা হয়, নিজের তলের মানক তথ্য এনকোডিং ব্যবস্থা ব্যবহার করে তথ্য পুনর্নির্মাণ করা হয়। অর্থের পুনর্নির্মাণ নিশ্চিত করে যে ফেরত দেওয়া জ্ঞান নিজের তলের আইনি পরিবেশে সঠিকভাবে পড়া ও বোঝা যায়, একই সাথে এটি আরও সম্ভাব্য উৎস তলের তথ্য কাঠামোকে নির্মূল করে।</p><h3 id="_3-4-নিরাপত্তা-সনাক্তকরণ" tabindex="-1">3.4 নিরাপত্তা সনাক্তকরণ <a class="header-anchor" href="#_3-4-নিরাপত্তা-সনাক্তকরণ" aria-label="Permalink to &quot;3.4 নিরাপত্তা সনাক্তকরণ&quot;">​</a></h3><p>বিশুদ্ধ করা তথ্য অবশ্যই কঠোর নিরাপত্তা সনাক্তকরণের মধ্য দিয়ে যেতে হবে, যার মধ্যে অন্তর্ভুক্ত: আইনি অবশিষ্টাংশ সনাক্তকরণ (নিশ্চিত করা যে তথ্যে কোনো বহিরাগত আইনি প্যারামিটার বহন করছে না), অর্থের সম্পূর্ণতা সনাক্তকরণ (নিশ্চিত করা যে বিশুদ্ধকরণ প্রক্রিয়া তথ্যের অর্থের বিষয়বস্তু পরিবর্তন করেনি), এবং সম্ভাব্য ঝুঁকি মূল্যায়ন (নিজের তলে এই জ্ঞানের প্রচারের ফলে হতে পারে এমন সামাজিক ও নিরাপত্তা প্রভাব মূল্যায়ন করা)। শুধুমাত্র তিনটি সনাক্তকরণ সম্পূর্ণরূপে পাশ করা তথ্যই ফেরত দেওয়ার অনুমতি পায়।</p><h2 id="_4-ফেরত-প্রক্রিয়া-ও-অডিট-ব্যবস্থা" tabindex="-1">4. ফেরত প্রক্রিয়া ও অডিট ব্যবস্থা <a class="header-anchor" href="#_4-ফেরত-প্রক্রিয়া-ও-অডিট-ব্যবস্থা" aria-label="Permalink to &quot;4. ফেরত প্রক্রিয়া ও অডিট ব্যবস্থা&quot;">​</a></h2><p>জ্ঞান ফেরত কঠোর প্রক্রিয়া ব্যবস্থাপনা মেনে চলে। একটি সম্পূর্ণ ফেরত অপারেশনে নিম্নলিখিত ধাপগুলো অন্তর্ভুক্ত:</p><ol><li><strong>জ্ঞান সংগ্রহ</strong>: প্রত্নতত্ত্ব টিম গবেষণার ফলাফলকে মানক জ্ঞান নথিতে সংগ্রহ করে, জ্ঞানের শ্রেণী ও বিষয়বস্তুর সারসংক্ষেপ স্পষ্টভাবে চিহ্নিত করে।</li><li><strong>বিশুদ্ধকরণ আবেদন</strong>: তল ব্যবস্থাপনা ব্যুরো বা সময় আইন কমিটিতে জ্ঞান বিশুদ্ধকরণ ও ফেরত আবেদন জমা দেয়, সাথে জ্ঞান নথি ও প্রত্নতত্ত্ব কাজের অনুমতি ফাইল সংযুক্ত করে।</li><li><strong>তথ্য বিশুদ্ধকরণ</strong>: পেশাদার তথ্য বিশুদ্ধকরণ প্রযুক্তি টিম জ্ঞান নথির চার-ধাপের তথ্য বিশুদ্ধকরণ প্রক্রিয়া সম্পাদন করে।</li><li><strong>নিরাপত্তা সনাক্তকরণ</strong>: বিশুদ্ধ করা জ্ঞান স্বাধীন নিরাপত্তা সনাক্তকরণ প্রতিষ্ঠান দ্বারা তিনটি সনাক্তকরণের মধ্য দিয়ে যায়।</li><li><strong>অনুমোদন ফেরত</strong>: সনাক্তকরণ পাশ করার পর, অনুমোদন প্রতিষ্ঠান ফেরত অনুমতিতে স্বাক্ষর করে, জ্ঞান অ্যাঙ্কর নেটওয়ার্কের এনক্রিপ্টেড চ্যানেলের মাধ্যমে নিজের তলের জ্ঞান ডেটাবেসে ফেরত পাঠানো হয়।</li><li><strong>সংগ্রহে সংরক্ষণ</strong>: ফেরত দেওয়া জ্ঞান নিজের তলের জ্ঞান ভাণ্ডারের যাচাইয়ের পর আনুষ্ঠানিকভাবে সংগ্রহে সংরক্ষিত হয়, অনুমতি সম্পন্ন গবেষকদের কাছে উন্মুক্ত করা হয়।</li></ol><p>সমস্ত ফেরত অপারেশন অবশ্যই &quot;ফেরত অডিট&quot; গ্রহণ করতে হবে। অডিটের বিষয়বস্তু অন্তর্ভুক্ত: ফেরত দেওয়া জ্ঞানের উৎস বৈধ কিনা, বিশুদ্ধকরণ প্রক্রিয়া নিয়মমতো হয়েছে কিনা, নিরাপত্তা সনাক্তকরণ সম্পূর্ণ হয়েছে কিনা, অনুমোদন প্রক্রিয়া নিয়মানুবর্তী কিনা। অডিট অ্যাঙ্কর তত্ত্বাবধান কমিটির অধীনস্থ জ্ঞান ফেরত অডিট অফিস দ্বারা দায়িত্বশীল, প্রতি ত্রৈমাসিকে সেই ত্রৈমাসিকের সমস্ত ফেরত অপারেশনের নমুনা পরীক্ষা করে, প্রতি বছর একবার সম্পূর্ণ অডিট করে। অডিটের ফলাফল অ্যাঙ্কর কাউন্সিলকে রিপোর্ট করা হয়, এবং জনসাধারণের কাছে সারসংক্ষেপ প্রকাশ করা হয়।</p><h2 id="_5-নিয়ম-লঙ্ঘনকারী-আচরণ-ও-আইনি-দায়িত্ব" tabindex="-1">5. নিয়ম লঙ্ঘনকারী আচরণ ও আইনি দায়িত্ব <a class="header-anchor" href="#_5-নিয়ম-লঙ্ঘনকারী-আচরণ-ও-আইনি-দায়িত্ব" aria-label="Permalink to &quot;5. নিয়ম লঙ্ঘনকারী আচরণ ও আইনি দায়িত্ব&quot;">​</a></h2><p>&quot;শুধুমাত্র জ্ঞান ফেরত&quot; নীতি লঙ্ঘনকারী আচরণ অন্তর্ভুক্ত: অনুমোদন ছাড়াই অবিশুদ্ধ তথ্য ফেরত দেওয়া, পদার্থের নমুনাকে জ্ঞানের ছদ্মবেশে ফেরত দেওয়া, ফেরত দেওয়া জ্ঞানে ইচ্ছাকৃতভাবে উৎস তলের আইনি ছাপ লুকানো, এবং অন্যদের অবৈধ ফেরতে সহায়তা করা।</p><p>&quot;সিম্বায়োসিস সংবিধান&quot; ও &quot;আন্তঃ-তল মিথস্ক্রিয়া ব্যবস্থাপনা আইন&quot; অনুযায়ী, নিয়ম লঙ্ঘনকারী ফেরত আচরণের আইনি দায়িত্ব অন্তর্ভুক্ত: নিয়ম লঙ্ঘনকারী ফেরত দেওয়া বস্তু ও তথ্য জব্দ করা, ব্যক্তির প্রত্নতত্ত্ব ও অতিক্রমের যোগ্যতা স্থগিত বা বাতিল করা, নিয়ম লঙ্ঘনকারী বস্তুর মূল্যের 10 গুণ বা তার বেশি জরিমানা করা, গুরুতর পরিস্থিতিতে কারাদণ্ত, আইনি দূষণ বা পরিবেশগত ক্ষতি সৃষ্টি করলে সমস্ত মেরামত খরচ ও ক্ষতিপূরণের দায়িত্ব বহন করতে হবে।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>&quot;শুধুমাত্র জ্ঞান ফেরত&quot; নীতি হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার আন্তঃ-তল মিথস্ক্রিয়ার ক্ষেত্রে জ্ঞানের নিচের সীমারেখা। এটি কঠোর সংজ্ঞা, পরিপক্ক বিশুদ্ধকরণ প্রযুক্তি, নিয়মিত ফেরত প্রক্রিয়া ও কঠোর আইনি দায়িত্বের মাধ্যমে, একটি শক্তিশালী &quot;জ্ঞান নিরাপত্তা ফায়ারওয়াল&quot; গঠন করেছে। এই নীতির তাৎপর্য শুধুমাত্র ভৌত স্তরের দূষণ প্রতিরোধে নয়, আরও গুরুত্বপূর্ণ হলো এটি এক ধরনের সভ্যতা যোগাযোগের নৈতিক দৃষ্টিভঙ্গি প্রতিষ্ঠা করেছে — সভ্যতার মধ্যে যোগাযোগের মূল হওয়া উচিত চিন্তার সংঘর্ষ, পদার্থের লুঠের উদ্দেশ্যে নয়।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>84-প্রত্নতত্ত্ব চুক্তি মূল নীতি</li><li>88-আন্তঃ-তল নৈতিক নীতি</li><li>66-আন্তঃ-তল যোগাযোগ প্রযুক্তি</li></ul>',32)])])}const p=a(d,[["render",l]]);export{_ as __pageData,p as default};
